CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS stocks (symbol VARCHAR(24) PRIMARY KEY,name VARCHAR(190),exchange VARCHAR(32),sector VARCHAR(100),industry VARCHAR(150),market_cap BIGINT NULL,pe DECIMAL(16,4) NULL,eps DECIMAL(16,6) NULL,dividend_yield DECIMAL(12,6) NULL,beta DECIMAL(12,6) NULL,revenue_growth DECIMAL(12,6) NULL,eps_growth DECIMAL(12,6) NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS prices (symbol VARCHAR(24) NOT NULL,ts DATETIME NOT NULL,open DECIMAL(18,6),high DECIMAL(18,6),low DECIMAL(18,6),close DECIMAL(18,6),volume BIGINT,PRIMARY KEY(symbol,ts),INDEX idx_prices_symbol_ts(symbol,ts)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS financials (symbol VARCHAR(24) NOT NULL,period_end DATE NOT NULL,revenue DECIMAL(24,4),net_income DECIMAL(24,4),free_cash_flow DECIMAL(24,4),total_debt DECIMAL(24,4),equity DECIMAL(24,4),PRIMARY KEY(symbol,period_end)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS watchlists (user_id INT UNSIGNED NOT NULL,symbol VARCHAR(24) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,symbol),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
